import{_ as o,o as t,c as i,aw as r}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Чистые функции (Pure Functions)","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/programming/fp-concept/pure-functions.md","filePath":"wiki/dev-commit/theory/programming/fp-concept/pure-functions.md"}'),a={name:"wiki/dev-commit/theory/programming/fp-concept/pure-functions.md"};function l(n,e,c,s,u,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="чистые-функции-pure-functions" tabindex="-1">Чистые функции (Pure Functions) <a class="header-anchor" href="#чистые-функции-pure-functions" aria-label="Permalink to &quot;Чистые функции (Pure Functions)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Чистые функции</p><ul><li><strong>Чистые функции</strong> - возвращает один и тот же результат для одинаковых входных данных</li></ul></div><ul><li>Не изменяет входные данные (иммутабельность)</li><li>Не зависит от внешнего состояния (базы данных, DOM или глобальной переменной)</li><li>Не имеет побочных эффектов (side effects): не влияют на состояние программы</li><li>Чистые функции могут вызывать только чистые функции</li></ul><h2 id="условия" tabindex="-1">Условия <a class="header-anchor" href="#условия" aria-label="Permalink to &quot;Условия&quot;">​</a></h2><ul><li><strong>Детерменированная</strong> - для одного и того же набора входных значений возвращает одинаковый результат</li><li><strong>Без побочных эффектов</strong> - в императивных языках некоторые функции в процессе выполнения своих вычислений могут модифицировать значения глобальных переменных, осуществлять операции ввода-вывода, реагировать на исключительные ситуации, вызывая их обработчики. Они называются функциями с побочными эффектами</li><li>Для замены циклов в JS можно использовать map и reduce</li></ul><h2 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h2><ul><li>Функция, которая вызвала <code>console.log()</code> не является чистой</li><li><code>console.log()</code> имеет Side effect, т.к. изменяет состояние консоли</li></ul>',7)])])}const f=o(a,[["render",l]]);export{m as __pageData,f as default};
